/** Convenience flag for tooling that wants to confirm Phase-2 fan-out. */
export const UE_COGNITION_TABLES = [
  ueCaseRiskSnapshots,
  ueWorkloadSnapshots,
  ueEngagementSnapshots,
  uePrecedentMatches,
  ueKpiSnapshots,
  ueCognitionAudits,
] as const

void boolean
